begin;
select plan(24);
select has_table('public','free_choice_availability_access','free-choice access table exists');
select ok((select relrowsecurity from pg_class where oid='public.free_choice_availability_access'::regclass),'RLS enabled');
select ok(not has_table_privilege('anon','public.free_choice_availability_access','select'),'anon cannot read access rows');
select ok(not has_table_privilege('authenticated','public.free_choice_availability_access','select'),'authenticated cannot read access rows');
select ok(not has_table_privilege('service_role','public.free_choice_availability_access','select'),'service role uses RPC only');
select ok(has_function_privilege('service_role','public.rotate_free_choice_availability_access(uuid,uuid,uuid,text,timestamptz,timestamptz,integer,timestamptz,timestamptz)','execute'),'service role can rotate');
select ok(not has_function_privilege('authenticated','public.rotate_free_choice_availability_access(uuid,uuid,uuid,text,timestamptz,timestamptz,integer,timestamptz,timestamptz)','execute'),'browser cannot rotate');
select ok(has_function_privilege('service_role','public.get_public_free_choice_availability_context(text,timestamptz)','execute'),'service role resolves context');
select ok(not has_function_privilege('anon','public.get_public_free_choice_availability_context(text,timestamptz)','execute'),'browser cannot resolve context directly');
select is((select proconfig from pg_proc where oid='public.rotate_free_choice_availability_access(uuid,uuid,uuid,text,timestamptz,timestamptz,integer,timestamptz,timestamptz)'::regprocedure),array['search_path=""'],'rotation fixes empty search path');
set local role service_role;
select public.activate_google_calendar_connection('20000000-0000-0000-0000-000000000001','10000000-0000-0000-0000-000000000001','v1.free-choice-ciphertext.tag',array['https://www.googleapis.com/auth/calendar.calendarlist.readonly','https://www.googleapis.com/auth/calendar.events.freebusy']);
select public.assign_artist_calendar('20000000-0000-0000-0000-000000000001','10000000-0000-0000-0000-000000000001','50000000-0000-0000-0000-000000000001','artist@example.test','writer');
select public.save_artist_availability_rules('20000000-0000-0000-0000-000000000001','10000000-0000-0000-0000-000000000001','50000000-0000-0000-0000-000000000001','Europe/Dublin',60,0,0,'[{"weekday":1,"start":"09:00","end":"12:00"}]');
select lives_ok($$select public.rotate_free_choice_availability_access('20000000-0000-0000-0000-000000000001','10000000-0000-0000-0000-000000000001','50000000-0000-0000-0000-000000000001',repeat('ab',32),'2026-09-21T00:00:00Z','2026-09-22T00:00:00Z',60,'2026-09-21T12:00:00Z','2026-09-20T08:00:00Z')$$,'OWNER issues compatible access');
reset role;
select is((select encode(token_hash,'hex') from public.free_choice_availability_access),repeat('ab',32),'only hash is stored');
set local role service_role;
select ok((select public.get_public_free_choice_availability_context(repeat('ab',32),'2026-09-20T09:00:00Z') ?& array['range_start','range_end','duration_minutes','expires_at','artist_display_name','time_zone','windows','calendar_id','connection','holds']),'server context is complete');
select ok((select not public.get_public_free_choice_availability_context(repeat('ab',32),'2026-09-20T09:00:00Z') ?| array['customer','tattoo_case','conversation','contact','event','title','description','token_hash']),'context excludes unrelated private details');
select lives_ok($$select public.rotate_free_choice_availability_access('20000000-0000-0000-0000-000000000001','10000000-0000-0000-0000-000000000001','50000000-0000-0000-0000-000000000001',repeat('cd',32),'2026-09-21T00:00:00Z','2026-09-22T00:00:00Z',60,'2026-09-21T12:00:00Z','2026-09-20T08:01:00Z')$$,'rotation succeeds');
select is(public.get_public_free_choice_availability_context(repeat('ab',32),'2026-09-20T09:00:00Z'),null::jsonb,'rotated hash fails uniformly');
select isnt(public.get_public_free_choice_availability_context(repeat('cd',32),'2026-09-20T09:00:00Z'),null::jsonb,'new hash resolves');
select is(public.get_public_free_choice_availability_context(repeat('cd',32),'2026-09-21T12:00:00Z'),null::jsonb,'exact expiry fails closed');
select throws_ok($$select public.rotate_free_choice_availability_access('20000000-0000-0000-0000-000000000002','10000000-0000-0000-0000-000000000003','50000000-0000-0000-0000-000000000001',repeat('ef',32),'2026-09-21T00:00:00Z','2026-09-22T00:00:00Z',60,'2026-09-21T12:00:00Z','2026-09-20T08:00:00Z')$$,'P0002',null,'cross-tenant artist rejected');
select throws_ok($$select public.rotate_free_choice_availability_access('20000000-0000-0000-0000-000000000001','10000000-0000-0000-0000-000000000002','50000000-0000-0000-0000-000000000001',repeat('ef',32),'2026-09-21T00:00:00Z','2026-09-22T00:00:00Z',60,'2026-09-21T12:00:00Z','2026-09-20T08:00:00Z')$$,'42501',null,'ARTIST cannot issue');
select throws_ok($$select public.get_public_free_choice_availability_context('ABC','2026-09-20T09:00:00Z')$$,'22023',null,'invalid hash rejected');
select ok(has_function_privilege('service_role','public.mark_public_free_choice_availability_reauth_required(text,bigint,timestamptz)','execute'),'service role can mark reconnect through token CAS');
select ok(not has_function_privilege('anon','public.mark_public_free_choice_availability_reauth_required(text,bigint,timestamptz)','execute'),'anon cannot mark reconnect');
reset role;
select is((select count(*) from public.free_choice_availability_access),1::bigint,'one credential per artist');
select * from finish();
rollback;
